int set_aa_process_attribute(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0 || task != current) {
        return -EINVAL;
    }

    char *value_str = value;
    size_t len = strnlen(value_str, size);
    if (len == size) {
        return -ERANGE;
    }

    char *command = strsep(&value_str, " ");
    if (!command || strlen(command) == 0) {
        return -EINVAL;
    }

    if (strcmp(name, "profile") == 0) {
        int result = aa_change_profile(task, command);
        if (result < 0) {
            audit_log_message("AA_ERROR", "Failed to change profile: %s", command);
            return result;
        }
    } else if (strcmp(name, "namespace") == 0) {
        int result = aa_change_namespace(task, command);
        if (result < 0) {
            audit_log_message("AA_ERROR", "Failed to change namespace: %s", command);
            return result;
        }
    } else {
        return -EINVAL;
    }

    return (int)size;
}

int aa_setprocattr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0) {
        return -EINVAL;
    }

    if (current != task) {
        return -EPERM;
    }

    char *str = kmalloc(size + 1, GFP_KERNEL);
    if (!str) {
        return -ENOMEM;
    }

    memcpy(str, value, size);
    str[size] = '\0';

    if (strcmp(name, "current") == 0) {
        int ret = aa_change_hat(str);
        kfree(str);
        if (ret < 0) {
            return ret;
        }
        return size;
    } else if (strcmp(name, "exec") == 0) {
        int ret = aa_change_hat_onexec(str);
        kfree(str);
        if (ret < 0) {
            return ret;
        }
        return size;
    } else {
        kfree(str);
        return -EINVAL;
    }
}

int apparmor_setprocattr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0) {
        return -EINVAL;
    }

    if (task != current) {
        return -EPERM;
    }

    char *command = value;
    if (!command) {
        return -EFAULT;
    }

    if (strncmp(name, "current", 7) == 0) {
        int result = apparmor_change_current_profile(command);
        if (result < 0) {
            audit_log_apparmor_failure(command, result);
            return result;
        }
    } else if (strncmp(name, "prev", 4) == 0) {
        int result = apparmor_change_previous_profile(command);
        if (result < 0) {
            audit_log_apparmor_failure(command, result);
            return result;
        }
    } else {
        return -EINVAL;
    }

    return size;
}

int set_apparmor_process_attribute(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0 || task != current) {
        return -EINVAL;
    }

    char *value_str = (char *)value;
    if (strnlen(value_str, size) == size) {
        return -ERANGE;
    }

    char *command = strsep(&value_str, ":");

    if (strncmp(name, "security", sizeof("security") - 1) == 0) {
        if (strncmp(command, "change_hat", sizeof("change_hat") - 1) == 0) {
            int ret = change_hat(task, value_str, size - strlen(command) - 1);
            if (ret < 0) {
                audit_log(current, AUDIT_APPARMOR, "change_hat_failed", 0);
                return ret;
            }
        } else if (strncmp(command, "change_profile", sizeof("change_profile") - 1) == 0) {
            int ret = change_profile(task, value_str, size - strlen(command) - 1);
            if (ret < 0) {
                audit_log(current, AUDIT_APPARMOR, "change_profile_failed", 0);
                return ret;
            }
        } else {
            audit_log(current, AUDIT_APPARMOR, "unsupported_command", 0);
            return -ENOSYS;
        }
    } else {
        audit_log(current, AUDIT_APPARMOR, "unsupported_attribute", 0);
        return -ENOSYS;
    }

    return (int)size;
}

#include <linux/sched.h>
#include <linux/audit.h>
#include <linux/errno.h>
#include <linux/string.h>

int apparmor_setprocattr(struct task_struct *task, char *name, void *value, size_t size)
{
    char *cmd;

    if (size == 0)
        return -EINVAL;

    if (current != task)
        return -EPERM;

    if (!value) {
        audit_log(current->audit_context, AUDIT_AA_SETPROCATTR, 0, "invalid value", 0);
        return -EINVAL;
    }

    if (strnlen(value, size) == size) {
        audit_log(current->audit_context, AUDIT_AA_SETPROCATTR, 0, "value not null-terminated", 0);
        return -EINVAL;
    }

    cmd = value;

    if (strcmp(name, "change_hat") == 0) {
        int ret = apparmor_change_hat(task, cmd);
        if (ret < 0) {
            audit_log(current->audit_context, AUDIT_AA_SETPROCATTR, 0, "failed to change_hat", 0);
            return ret;
        }
    } else {
        audit_log(current->audit_context, AUDIT_AA_SETPROCATTR, 0, "unknown attribute", 0);
        return -EINVAL;
    }

    return (int)size;
}
